/**
 * Shapely 2.1.2 (GEOS) reference results for the pinned relate scenes of
 * `spatial-relate-scenes.ts`, generated once outside the tests (`shapely.relate` and the named
 * predicates); the specs never call Python. Each entry covers the scene of one `left-right` kind
 * pair: `left` x `right` features in row-major order, `relate` is the concatenated 9-character
 * DE-9IM string of every pair and each predicate is a string of `0`/`1` per pair.
 */
export type ShapelyRelateFixture = {
  left: number;
  right: number;
  relate: string;
  predicates: Record<string, string>;
};

